26118,"c":15082,"length":50,"sets":1}],"upstream":14559.216637894511,"sourceI":12399.602215226118,"rows":[{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":12399.602215226118,"source":12399.602215226118,"basis":"Utility point-to-point"}],"maximum":{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":12399.602215226118,"source":12399.602215226118,"basis":"Utility point-to-point"}},"sub2":{"i":9781.263083841064,"v":480,"phase":3,"steps":[{"input":14559.216637894511,"output":9781.263083841064,"c":10755,"length":100,"sets":1}],"upstream":14559.216637894511,"sourceI":9781.263083841064,"rows":[{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":9781.263083841064,"source":9781.263083841064,"basis":"Utility point-to-point"}],"maximum":{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":9781.263083841064,"source":9781.263083841064,"basis":"Utility point-to-point"}},"sub3":{"i":6237.669754488538,"v":480,"phase":3,"steps":[{"input":14559.216637894511,"output":6237.669754488538,"c":5907,"length":150,"sets":1}],"upstream":14559.216637894511,"sourceI":6237.669754488538,"rows":[{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":6237.669754488538,"source":6237.669754488538,"basis":"Utility point-to-point"}],"maximum":{"caseId":"utility","caseName":"Utility","fault":"3Ø","amps":6237.669754488538,"source":6237.669754488538,"basis":"Utility point-to-point"}}},"errors":[],"notes":[],"engineVersion":"northgate-afc/1.0.0","dataVersion":"eaton-2014-table4-600v-single-conductors"}$results$;
 request uuid:=gen_random_uuid();save_request uuid:=gen_random_uuid();audit_id uuid:=gen_random_uuid();
 d public.documents;before_time timestamptz;blocked boolean;kind text;
BEGIN
 SELECT clerk_user_id INTO STRICT actor FROM public.user_permissions WHERE lower(email)='crncmk@gmail.com' AND is_active;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 j:=public.create_job('Electrical','PHASES-SMOKE-'||gen_random_uuid()::text,'ROLLBACK ONLY AFC destination','on_hold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'job',NULL,actor);
 s:=public.afc_save(save_request,NULL,NULL,doc,'Electrical',j.id);
 ASSERT (s->>'version')::int=1,'AFC shared draft failed';
 ASSERT public.afc_save(save_request,NULL,NULL,doc,'Electrical',j.id)=s,'Draft retry duplicated state';
 blocked:=false;BEGIN PERFORM public.afc_save(gen_random_uuid(),(s->>'id')::uuid,0,doc,'Electrical',j.id);EXCEPTION WHEN serialization_failure THEN blocked:=true;END;ASSERT blocked,'Stale save accepted';
 blocked:=false;BEGIN PERFORM public.afc_release_context((s->>'id')::uuid,1,request);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;ASSERT blocked,'Reviewer authority granted implicitly';
 RESET ROLE;
 ASSERT NOT has_table_privilege('authenticated','public.afc_studies','UPDATE'),'Direct AFC writes exposed';
 ASSERT NOT has_function_privilege('authenticated','public.afc_finalize_release(text,uuid,integer,uuid,jsonb,jsonb,text,timestamptz)','EXECUTE'),'Client release finalizer exposed';
 ASSERT NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND (p.proname LIKE 'afc_%' OR p.proname LIKE 'northgate_%') AND has_function_privilege('anon',p.oid,'EXECUTE')),'Anonymous endpoint exposed';
 -- Temporary fixture permission exists only inside this transaction.
 INSERT INTO public.user_permission_overrides(user_id,permission_flag,granted,granted_by_user_id,reason)VALUES(actor,'can_review_afc_studies',true,actor,'Rollback-only release verification');
 SET LOCAL ROLE authenticated;
 ctx:=public.afc_release_context((s->>'id')::uuid,1,request);
 res:=res||jsonb_build_object('releaseContext',jsonb_build_object('reviewerName',ctx->'reviewer_name','jobSnapshot',ctx->'job_snapshot','reviewedAt',ctx->'reviewed_at'));
 RESET ROLE;
 FOREACH kind IN ARRAY ARRAY['report','labels','source'] LOOP
  f:=jsonb_build_object('id',gen_random_uuid(),'kind',kind,'file_name',kind||CASE WHEN kind='source' THEN '.json' ELSE '.pdf' END,'storage_path','afc/'||(s->>'id')||'/'||request||'/'||gen_random_uuid()||'/'||kind,'size',20,'sha256',repeat('a',64));files:=files||jsonb_build_array(f);
 END LOOP;
 SET LOCAL ROLE service_role;
 blocked:=false;BEGIN PERFORM public.afc_finalize_release(actor,(s->>'id')::uuid,1,request,res,files,'Synthetic rollback-only review',(ctx->>'reviewed_at')::timestamptz);EXCEPTION WHEN raise_exception THEN blocked:=position('file is missing' in SQLERRM)>0;END;ASSERT blocked,'Missing files published';
 RESET ROLE;
 ASSERT NOT EXISTS(SELECT 1 FROM public.afc_revisions WHERE study_id=(s->>'id')::uuid),'Failed release left revision';
 FOR f IN SELECT value FROM jsonb_array_elements(files) LOOP INSERT INTO storage.objects(bucket_id,name,metadata)VALUES('northgate-files',f->>'storage_path','{"size":20}');END LOOP;
 SET LOCAL ROLE service_role;
 released:=public.afc_finalize_release(actor,(s->>'id')::uuid,1,request,res,files,'Synthetic rollback-only review',(ctx->>'reviewed_at')::timestamptz);
 ASSERT released->>'status'='reviewed','Release failed';
 ASSERT public.afc_finalize_release(actor,(s->>'id')::uuid,1,request,res,files,'Synthetic rollback-only review',(ctx->>'reviewed_at')::timestamptz)=released,'Release retry changed history';
 RESET ROLE;
 ASSERT (SELECT count(*)=3 FROM public.afc_files WHERE revision_id=request),'Incomplete archive';
 ASSERT (SELECT document_section='electrical' AND owner_id=j.id FROM public.documents WHERE id=(files->0->>'id')::uuid),'Canonical destination/section incorrect';
 SET LOCAL ROLE authenticated;
 SELECT * INTO d FROM public.documents WHERE id=(files->0->>'id')::uuid;
 blocked:=false;BEGIN PERFORM public.maintain_owner_document(d.id,'job',j.id,'edit','{"file_name":"overwrite.pdf","document_type":"misc"}','Attempt overwrite',d.updated_at);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;ASSERT blocked,'Released file editable';
 s:=public.afc_save(gen_random_uuid(),(s->>'id')::uuid,(released->>'version')::int,jsonb_set(doc,'{title}','"Revised rollback-only study"'),'Electrical',NULL);
 ASSERT s->>'status'='draft','Edit failed to create new draft';
 ASSERT (public.afc_read((s->>'id')::uuid)->'revisions'->0->'job_snapshot'->>'id')=j.id::text,'Historical destination was changed';
 INSERT INTO public.documents(division,owner_type,owner_id,storage_path,file_name,document_type,created_by)VALUES('Electrical','job',j.id,'documents/job/'||j.id||'/smoke.pdf','smoke.pdf','plans',actor)RETURNING * INTO d;
 ASSERT d.document_section IS NULL,'Ambiguous document was reclassified';before_time:=d.updated_at;
 d:=public.set_document_section(d.id,'construction',d.updated_at);ASSERT d.document_section='construction','Classification failed';
 -- The existing updated-at trigger uses transaction NOW(); emulate an earlier request timestamp.
 blocked:=false;BEGIN PERFORM public.set_document_section(d.id,'general',before_time-interval '1 second');EXCEPTION WHEN serialization_failure THEN blocked:=true;END;ASSERT blocked,'Stale classification accepted';
 blocked:=false;BEGIN UPDATE public.documents SET document_section='general' WHERE id=d.id;EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;ASSERT blocked,'Direct classification accepted';
 PERFORM public.northgate_read_context();
 PERFORM public.northgate_audit_read(audit_id,'get_job_summary',jsonb_build_object('id',j.id),'started');
 PERFORM public.northgate_audit_read(audit_id,'get_job_summary',jsonb_build_object('id',j.id),'succeeded');
 ASSERT EXISTS(SELECT 1 FROM public.northgate_tool_reads WHERE request_id=audit_id AND outcome='succeeded'),'Read audit missing';
 PERFORM set_config('request.jwt.claims','{"sub":"phases-unauthorized-fixture","role":"authenticated"}',true);
 blocked:=false;BEGIN PERFORM public.afc_read((s->>'id')::uuid);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;ASSERT blocked,'Unauthorized study access';
 ASSERT NOT EXISTS(SELECT 1 FROM public.northgate_tool_reads WHERE request_id=audit_id),'Unauthorized audit access';
 RESET ROLE;
 INSERT INTO phases_smoke_result VALUES(jsonb_build_object('pass',true,'checks','draft/retry/stale; reviewer denial; service-only release; missing-file rollback; immutable revision; original destination; metadata classification/stale/direct denial; read audit/RLS; transaction rolled back'));
END $smoke$;
SELECT result FROM phases_smoke_result;
ROLLBACK;
